import React from 'react';
import toast from 'react-hot-toast';
import {
  downloadEmailLogTxt,
  downloadEmailLogExcel,
  triggerDownload,
  downloadPartywiseExcel,
} from '../services/api';
import { FileText, FileSpreadsheet, Download } from 'lucide-react';

export default function EmailLogDownload({ matchedResults }) {
  const handleTxt = async () => {
    try {
      const res = await downloadEmailLogTxt();
      triggerDownload(res.data, 'FinalEmailLog.txt');
    } catch {
      toast.error('No log available yet. Send emails first.');
    }
  };

  const handleExcel = async () => {
    try {
      const res = await downloadEmailLogExcel();
      const timestamp = new Date().toISOString().slice(0, 19).replace(/[:.]/g, '-');
      triggerDownload(res.data, `FinalEmailLog_${timestamp}.xlsx`);
    } catch {
      toast.error('No log available yet. Send emails first.');
    }
  };

  const handlePartywise = async () => {
    try {
      const res = await downloadPartywiseExcel();
      const timestamp = new Date().toISOString().slice(0, 10);
      triggerDownload(res.data, `All_Partywise_Payments_${timestamp}.xlsx`);
    } catch {
      toast.error('No reconciliation data available. Upload and process an Excel first.');
    }
  };

  return (
    <div className="log-download">
      <p className="log-info">
        Download your email activity log or all party-wise payment sheets.
        Logs are stored in MongoDB and persist across sessions.
      </p>
      <div className="row gap-3 flex-wrap">
        <button className="btn btn-secondary" onClick={handleTxt}>
          <FileText size={16} /> Download Email Log (.txt)
        </button>
        <button className="btn btn-secondary" onClick={handleExcel}>
          <FileSpreadsheet size={16} /> Download Email Log (.xlsx)
        </button>
        {matchedResults?.length > 0 && (
          <button className="btn btn-secondary" onClick={handlePartywise}>
            <Download size={16} /> Download All Party-wise Payments (.xlsx)
          </button>
        )}
      </div>
    </div>
  );
}
